      "content": "// dsh-plugin-guard — install safety net for DeepSeek Harness.\n//\n// In-process half (this plugin):\n//  1. systemPrompt section (order -50, before the persona): when\n//     $DSH_HOME/guard/pending-incident.json exists it injects an instruction\n//     that makes the pending incident the session's first task.\n//  2. Tools: incident_resolved, dsh_snapshot, dsh_rollback.\n//  3. Pre-tool guard: automatically snapshots every profile before\n//     plugin_install / plugin_uninstall / plugin_toggle run (never denies).\n//  4. HTTP API (via webServer, when present) backing the 设置 > 备份管理\n//     panel: state / snapshot / rollback / keep.\n//\n// Out-of-process halves (scripts/): standalone CLI (`dsh-guard`), boot guard\n// scripts for Windows and POSIX, and PATH shims — see README.\nimport { snapshotAll, snapshotProfile, listProfiles, listSnapshots, resolveSnapshotDir, restoreSnapshot, readGuardConfig, setKeepSnapshots, DEFAULT_KEEP_SNAPSHOTS, MIN_KEEP_SNAPSHOTS, MAX_KEEP_SNAPSHOTS } from './engine.js'\nimport { incidentSectionText, readPending, resolveIncidentMarker } from './incident.js'\nimport { createGuardTools } from './tools.js'\nimport z from '@deepseek-ai/schemastery'\n\nexport const name = 'guard'\n\nconst GUARDED_TOOLS = new Set(['plugin_install', 'plugin_uninstall', 'plugin_toggle'])\n\n// Host-side settings scope for this plugin's own namespace (`guard`), set when\n// the settings service is available. keepSnapshots stays authoritative in\n// guard/config.json (CLI/boot-guard mirror); the scope is the validated write\n// path used by the web 设置 surface and the Plugins-tab settings card.\nlet guardSettingsScope = null\n\n// ── tiny HTTP helpers (plain node:http) ──\nconst errMsg = (e) => (e && e.message) ? e.message : String(e)\n\nfunction send(res, data, status = 200) {\n  res.statusCode = status\n  res.setHeader('Content-Type', 'application/json; charset=utf-8')\n  res.setHeader('Cache-Control', 'no-store')\n  res.end(JSON.stringify(data))\n}\n\nfunction readBody(req) {\n  return new Promise((resolve) => {\n    const chunks = []\n    req.on('data', (c) => chunks.push(c))\n    req.on('end', () => {\n      try {\n        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}'))\n      } catch {\n        resolve({})\n      }\n    })\n    req.on('error', () => resolve({}))\n  })\n}\n\n// ── API handlers ──\nasync function handleState(_req, res) {\n  try {\n    const profiles = listProfiles().map((p) => ({\n      name: p,\n      snapshots: listSnapshots(p).map((s) => ({\n        stamp: s.stamp,\n        tag: s.tag,\n        time: s.time,\n        reason: s.reason,\n      })),\n    }))\n    send(res, { ok: true, keepSnapshots: readGuardConfig().keepSnapshots, profiles })\n  } catch (e) { send(res, { ok: false, error: errMsg(e) }) }\n}\n\nasync function handleSnapshot(req, res) {\n  try {\n    const body = await readBody(req)\n    const profile = typeof body.profile === 'string' && body.profile !== '' ? body.profile : undefined\n    const results = profile\n      ? [snapshotProfile(profile, { tag: 'manual', reason: '手动存档（设置页）' })]\n      : snapshotAll('manual', '手动存档（设置页）')\n    send(res, { ok: true, results: results.map((r) => r.error ? { profile: r.profile, error: r.error } : r.skipped ? { profile: r.profile, skipped: true } : { profile: r.profile, stamp: r.stamp }) })\n  } catch (e) { send(res, { ok: false, error: errMsg(e) }) }\n}\n\nasync function handleRollback(req, res) {\n  try {\n    const body = await readBody(req)\n    const profile = typeof body.profile === 'string' && body.profile !== '' ? body.profile : 'web'\n    const stamp = typeof body.stamp === 'string' ? body.stamp : ''\n    if (!stamp) return send(res, { ok: false, error: '缺少要加载的快照 stamp' })\n    const dir = resolveSnapshotDir(profile, { id: stamp })\n    if (!dir) return send(res, { ok: false, error: `profile \"${profile}\" 找不到快照 ${stamp}` })\n    const { pnpm } = restoreSnapshot(profile, dir)\n    const target = dir.split(/[\\\\/]/).at(-1)\n    if (pnpm !== null && !pnpm.ok) {\n      return send(res, { ok: true, restored: true, stamp: target, warning: `配置文件已还原；pnpm install 失败（exit ${pnpm.status}）：${pnpm.output}` })\n    }\n    send(res, { ok: true, restored: true, stamp: target, note: '请重启应用使更改生效。' })\n  } catch (e) { send(res, { ok: false, error: errMsg(e) }) }\n}\n\nasync function handleKeep(req, res) {\n  try {\n    const body = await readBody(req)\n    const num = setKeepSnapshots(Number(body.keep))\n    // Keep the settings namespace in sync so the 设置 > 插件 card reflects the\n    // same value (the namespace schema validates 2-100; config.json is already\n    // authoritative and written above).\n    if (guardSettingsScope !== null) {\n      try { await guardSettingsScope.update({ keepSnapshots: num }) } catch { /* config.json wins; ignore */ }\n    }\n    send(res, { ok: true, keepSnapshots: num })\n  } catch (e) { send(res, { ok: false, error: errMsg(e) }) }\n}\n\n// ── 客户端渲染心跳 / 崩溃回报（黑屏检测）。rc.7 的客户端渲染失败是纯浏览器\n// 侧事件，服务端 HTTP 仍返回 200；guard 客户端在根槽位渲染成功时 POST\n// /guard/api/booted，在根槽位渲染崩溃时 POST /guard/api/render-error，守护\n// 脚本据此区分\"服务已起\"与\"客户端真的能用\"。均为进程内内存标志。──\nlet guardClientBooted = false\nlet guardRenderError = null // string message; null = 无渲染崩溃\n\nasync function handleBooted(req, res) {\n  try {\n    if (req.method === 'POST') {\n      guardClientBooted = true\n      return send(res, { ok: true, booted: true })\n    }\n    send(res, { ok: true, booted: guardClientBooted })\n  } catch (e) { send(res, { ok: false, error: errMsg(e) }) }\n}\n\nasync function handleRenderError(req, res) {\n  try {\n    if (req.method === 'POST') {\n      const body = await readBody(req)\n      guardRenderError = (body && typeof body.message === 'string' && body.message !== '')\n        ? body.message : '(client render error)'\n      return send(res, { ok: true, renderError: true })\n    }\n    // GET carries BOTH signals so the boot-guard can confirm health or crash\n    // from this single endpoint.\n    send(res, { ok: true, renderError: guardRenderError !== null, message: guardRenderError ?? '', booted: guardClientBooted })\n  } catch (e) { send(res, { ok: false, error: errMsg(e) }) }\n}\n\nexport function apply(ctx) {\n  // 1. Incident-alert prompt section.\n  const sp = ctx.get('systemPrompt')\n  if (sp !== undefined) {\n    sp.section({\n      name: 'guard:incident-alert',\n      order: -50,\n      text: () => incidentSectionText(),\n    })\n  }\n\n  // 2. Pre-tool guard + guard tools. Auto-snapshot before mutating install\n  // tools. Side-effect only: a guard never denies; snapshot errors are\n  // swallowed so the install itself is never blocked by the safety net.\n  const tools = ctx.get('tools')\n  if (tools !== undefined) {\n    tools.guard((execution) => {\n      if (GUARDED_TOOLS.has(execution.name)) {\n        try {\n          snapshotAll('auto-before-install', `pre-tool guard for ${execution.name}`)\n        } catch {\n          // never block the install because the guard failed\n        }\n      }\n      return undefined\n    })\n\n    for (const tool of createGuardTools()) {\n      tools.register(tool)\n    }\n  }\n\n  // 3. 设置 > 备份管理 HTTP API. Registered from the single guard row when a\n  // webServer exists; absent for non-web profiles (no separate apiOnly row).\n  // ctx.inject waits for webServer instead of a point-in-time ctx.get so the\n  // routes are registered even if webServer mounts after this row; it is\n  // non-blocking — a profile without webServer simply never gets the routes.\n  ctx.inject(['webServer'], (wctx) => {\n    const routes = [\n      { kind: 'exact', path: '/guard/api/state', handler: handleState },\n      { kind: 'exact', path: '/guard/api/snapshot', handler: handleSnapshot },\n      { kind: 'exact', path: '/guard/api/rollback', handler: handleRollback },\n      { kind: 'exact', path: '/guard/api/keep', handler: handleKeep },\n      { kind: 'exact', path: '/guard/api/booted', handler: handleBooted },\n      { kind: 'exact', path: '/guard/api/render-error', handler: handleRenderError },\n    ]\n    for (const route of routes) {\n      wctx.effect(() => wctx.webServer.register(route), `guard: ${route.path} route`)\n    }\n  })\n\n  // 4. rc.7 plugin-owned settings surface: register a `guard` namespace so the\n  // plugin appears in 设置 > 插件 > 插件配置 as a configurable card (schema\n  // validated + revision fenced via ctx.settings). config.json stays the\n  // authoritative store for the out-of-process CLI/boot-guard: the settings doc\n  // is seeded from it and every namespace change mirrors back into it. All of\n  // this is best-effort — a settings/llm failure must never break the guard.\n  ctx.inject(['settings'], (sctx) => {\n    try {\n      const cfg = readGuardConfig()\n      const scope = sctx.settings.register('guard', z.object({\n        keepSnapshots: z.number().min(MIN_KEEP_SNAPSHOTS).max(MAX_KEEP_SNAPSHOTS).default(cfg.keepSnapshots),\n      }), { base: { keepSnapshots: cfg.keepSnapshots } })\n      guardSettingsScope = scope\n      // seed the settings document from config.json so the card matches the CLI\n      void scope.update({ keepSnapshots: cfg.keepSnapshots }).catch(() => {})\n      // mirror every settings change back to config.json (CLI/boot-guard truth)\n      scope.watch(() => {\n        try {\n          const v = scope.get()\n          if (v && Number.isFinite(v.keepSnapshots)) setKeepSnapshots(v.keepSnapshots)\n        } catch { /* best effort */ }\n      })\n      // Expose the namespace to the web configuration boundary; without this\n      // directory entry the browser settingsScope binder reports it as\n      // unavailable (same pattern as dsh-vision-router).\n      const llm = ctx.get('llm')\n      if (llm !== undefined) {\n        try {\n          llm.registerConfigurableProviders([{ provider: 'guard', displayName: '备份管理（dsh-plugin-guard）' }])\n        } catch { /* best effort */ }\n      }\n    } catch {\n      // settings unavailable — the guard runs without the namespace\n    }\n    sctx.effect(() => () => { guardSettingsScope = null }, 'guard: settings scope teardown')\n  })\n}\n\nexport { readPending, resolveIncidentMarker }\n"
    },
    {
      "path": "src/layout.js",
      "content": "// Layout: every path this package touches is anchored at DSH_HOME so the\n// plugin (in-process), the CLI and the boot guard scripts (out-of-process)\n// share one state directory.\n//\n//   $DSH_HOME/rollbacks/<profile>/<stamp>/   profile snapshots\n//   $DSH_HOME/guard/logs/                    boot/server logs, incident reports\n//   $DSH_HOME/guard/pending-incident.json    pending incident marker\n//\nimport { homedir } from 'node:os'\nimport { join, resolve } from 'node:path'\n\nexport function dshHome() {\n  if (process.env.DSH_HOME && process.env.DSH_HOME.trim() !== '') {\n    return resolve(process.env.DSH_HOME.trim())\n  }\n  return join(homedir(), '.dsh')\n}\n\nexport function profilesDir() {\n  return join(dshHome(), 'profiles')\n}\n\nexport function profileDir(name) {\n  return join(profilesDir(), name)\n}\n\nexport function rollbacksRoot(profile) {\n  return join(dshHome(), 'rollbacks', profile)\n}\n\nexport function guardDir() {\n  return join(dshHome(), 'guard')\n}\n\nexport function guardLogsDir() {\n  return join(guardDir(), 'logs')\n}\n\nexport function pendingMarkerPath() {\n  return join(guardDir(), 'pending-incident.json')\n}\n\nexport function guardConfigPath() {\n  return join(guardDir(), 'config.json')\n}\n\n/** Files captured by every snapshot (the complete install-state metadata).\n * cordis.yml is the profile composition root — MCP servers are added there as\n * dsh-mcp-client instances, so it must be snapshotted/restored too or a bad\n * MCP config would survive rollback and keep breaking boot. */\nexport const SNAPSHOT_FILES = [\n  'package.json',\n  'pnpm-lock.yaml',\n  'pnpm-workspace.yaml',\n  'cordis.yml',\n  'cordis.patch.yml',\n]\n"
    },
    {
      "path": "src/engine.js",
      "content": "// Snapshot/rollback engine. Plain synchronous Node builtins only, so it works\n// identically inside the harness process (plugin tools, pre-tool guard) and\n// from the standalone CLI.\nimport {\n  existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync,\n  copyFileSync, rmSync, statSync, renameSync, lstatSync, readlinkSync,\n} from 'node:fs'\nimport { createHash } from 'node:crypto'\nimport { spawnSync } from 'node:child_process'\nimport { join, dirname, resolve, sep } from 'node:path'\nimport yaml from 'js-yaml'\nimport {\n  dshHome, profilesDir, profileDir, rollbacksRoot, guardDir, guardLogsDir, guardConfigPath, SNAPSHOT_FILES,\n} from './layout.js'\n\nexport const DEFAULT_KEEP_SNAPSHOTS = 10\nexport const MIN_KEEP_SNAPSHOTS = 2\nexport const MAX_KEEP_SNAPSHOTS = 100\nexport const DEFAULT_PORT = 3080\n/** How many boot/server logs, incident reports and resolved-incident markers\n * to keep per category; the oldest are pruned on every snapshot/incident. */\nexport const DEFAULT_KEEP_LOGS = 30\n\n/** Resolved DeepSeek Harness (dsh) version, recorded in every snapshot for\n * provenance. Reads the installed @deepseek-ai/dsh package next to DSH_HOME;\n * falls back to the root package.json dependency spec. Returns '' when\n * unresolvable (never throws). */\nexport function harnessVersion() {\n  const root = dirname(dshHome())\n  try {\n    const pkg = JSON.parse(readFileSync(join(root, 'node_modules', '@deepseek-ai', 'dsh', 'package.json'), 'utf8'))\n    if (typeof pkg.version === 'string' && pkg.version !== '') return pkg.version\n  } catch { /* fall through */ }\n  try {\n    const rootPkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))\n    const spec = rootPkg?.dependencies?.['@deepseek-ai/dsh']\n    if (typeof spec === 'string' && spec !== '') return `spec:${spec}`\n  } catch { /* unresolvable */ }\n  return ''\n}\n\n/** Read the guard settings file ($DSH_HOME/guard/config.json). Never throws;\n * malformed/missing config falls back to defaults. */\nexport function readGuardConfig() {\n  let cfg = null\n  try {\n    cfg = JSON.parse(readFileSync(guardConfigPath(), 'utf8'))\n  } catch { /* fallthrough */ }\n  const out = { keepSnapshots: DEFAULT_KEEP_SNAPSHOTS, port: DEFAULT_PORT }\n  if (cfg && typeof cfg === 'object') {\n    const n = Math.floor(Number(cfg.keepSnapshots))\n    if (Number.isFinite(n) && n >= MIN_KEEP_SNAPSHOTS && n <= MAX_KEEP_SNAPSHOTS) out.keepSnapshots = n\n    const p = Math.floor(Number(cfg.port))\n    if (Number.isFinite(p) && p >= 1 && p <= 65535) out.port = p\n  }\n  return out\n}\n\nconst escapeRegex = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\n\n/** The profile's known plugin rows: patch insert rows (quarantineable via a\n * `disabled` override) plus bundle/link-dep package names (informational only).\n * Returns [{ id, name, patch }]. */\nexport function profilePluginRows(profile) {\n  const dir = profileDir(profile)\n  const rows = []\n  const seen = new Set()\n  const add = (id, name, patch) => {\n    if (!id || seen.has(id)) return\n    seen.add(id)\n    rows.push({ id, name: name || id, patch: patch === true })\n  }\n  try {\n    const y = yaml.load(readFileSync(join(dir, 'cordis.patch.yml'), 'utf8'))\n    if (Array.isArray(y)) {\n      for (const e of y) {\n        if (e && Array.isArray(e.insert)) {\n          for (const r of e.insert) {\n            if (r && typeof r.id === 'string') add(r.id, typeof r.name === 'string' ? r.name : r.id, true)\n          }\n        }\n      }\n    }\n  } catch { /* unparseable patch -> no patch rows */ }\n  try {\n    const pkg = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'))\n    const bundles = pkg?.dsh?.profile?.bundles\n    if (Array.isArray(bundles)) for (const b of bundles) add(b, b, false)\n    const deps = pkg?.dependencies ?? {}\n    for (const [name, spec] of Object.entries(deps)) {\n      if (typeof spec === 'string' && spec.trim().toLowerCase().startsWith('link:')) add(name, name, false)\n    }\n  } catch { /* ignore */ }\n  return rows\n}\n\n/** Extract the package names implicated by a boot failure. Handles both the\n * mount-phase abort format — `failed to <stage> loader entry <id> (<name>):`\n * (this harness's main boot-period plugin failure) — and the tree-settle\n * summary — `plugin(s) failed to load: A, B`. Each token is matched exactly\n * against the profile's patch rows later, so over-capture here is avoided by\n * taking only clean package-name tokens. */\nexport function extractFailedPluginNames(logText) {\n  const names = []\n  if (!logText) return names\n  const push = (n) => { const t = String(n || '').trim(); if (t && !names.includes(t)) names.push(t) }\n  // loader-entry mount failure: \"failed to apply loader entry <id> (<name>): ...\"\n  const entryRe = /failed to \\S+ loader entry \\S+ \\(([^)]+)\\):/gi\n  let m\n  while ((m = entryRe.exec(logText))) push(m[1])\n  // tree-settle summary: \"plugin(s) failed to load: A, B\"\n  const settle = logText.match(/plugin\\(s\\) failed to load:\\s*([^;\\n]+)/i)\n  if (settle) {\n    for (const raw of settle[1].split(',')) push(raw.replace(/[()]/g, ''))\n  }\n  return names\n}\n\nfunction latestLogText(dir, re) {\n  try {\n    const files = readdirSync(dir).filter((f) => re.test(f)).sort()\n    if (files.length === 0) return ''\n    return readFileSync(join(dir, files.at(-1)), 'utf8')\n  } catch { return '' }\n}\n\n/** Diagnose which plugin broke this boot: parse the latest server (err + out)\n * and boot logs for either the loader-entry mount failure or the tree-settle\n * summary, and map the first implicated name to a quarantineable patch row id\n * (matching by package name OR row id). Returns { id, name } (id null when the\n * culprit is a bundle/dep that cannot be disabled by a patch override), or\n * null when no plugin is implicated. */\nexport function diagnoseCulprit(profile) {\n  const logs = guardLogsDir()\n  const errText = latestLogText(logs, /^server-.*\\.err\\.log$/)\n  const outText = latestLogText(logs, /^server-.*\\.out\\.log$/)\n  const bootText = latestLogText(logs, /^boot-.*\\.log$/)\n  const text = `${errText}\\n${outText}\\n${bootText}`\n  const names = extractFailedPluginNames(text)\n  if (names.length === 0) return null\n  const rows = profilePluginRows(profile)\n  for (const name of names) {\n    const row = rows.find((r) => r.patch && (r.name === name || r.id === name))\n    if (row) return { id: row.id, name }\n  }\n  return { id: null, name: names[0] }\n}\n\n/** Disable a patch-row plugin by appending a `disabled: true` override to the\n * profile's cordis.patch.yml, and record it in guard/quarantine.json. */\nexport function quarantinePlugin(profile, id) {\n  const dir = profileDir(profile)\n  const patchPath = join(dir, 'cordis.patch.yml')\n  const block = `- id: ${id}\\n  disabled: true\\n`\n  let text = ''\n  try { text = readFileSync(patchPath, 'utf8') } catch { text = '' }\n  if (!new RegExp(`- id: ${escapeRegex(id)}\\\\s*\\\\n\\\\s*disabled:\\\\s*true`).test(text)) {\n    const sep = text.endsWith('\\n') ? '' : '\\n'\n    writeFileSync(patchPath, text + sep + block, 'utf8')\n  }\n  mkdirSync(guardDir(), { recursive: true })\n  const qPath = join(guardDir(), 'quarantine.json')\n  let list = []\n  try { list = JSON.parse(readFileSync(qPath, 'utf8')) } catch { list = [] }\n  if (!Array.isArray(list)) list = []\n  list.push({ id, time: new Date().toISOString() })\n  writeFileSync(qPath, `${JSON.stringify(list, null, 2)}\\n`, 'utf8')\n  return { ok: true, id }\n}\n\n/** Remove the `disabled: true` override for a plugin and drop it from\n * guard/quarantine.json. */\nexport function unquarantinePlugin(profile, id) {\n  const dir = profileDir(profile)\n  const patchPath = join(dir, 'cordis.patch.yml')\n  let text = ''\n  try { text = readFileSync(patchPath, 'utf8') } catch { text = '' }\n  const re = new RegExp(`- id: ${escapeRegex(id)}\\\\s*\\\\n\\\\s*disabled:\\\\s*true\\\\s*\\\\n?`)\n  const next = text.replace(re, '')\n  if (next !== text) writeFileSync(patchPath, next, 'utf8')\n  const qPath = join(guardDir(), 'quarantine.json')\n  try {\n    const list = JSON.parse(readFileSync(qPath, 'utf8'))\n    const kept = Array.isArray(list) ? list.filter((e) => e && e.id !== id) : []\n    writeFileSync(qPath, `${JSON.stringify(kept, null, 2)}\\n`, 'utf8')\n  } catch { /* ignore */ }\n  return { ok: true, id }\n}\n\n/** Every recorded quarantine [{ id, time }]. */\nexport function readQuarantines() {\n  try {\n    const list = JSON.parse(readFileSync(join(guardDir(), 'quarantine.json'), 'utf8'))\n    return Array.isArray(list) ? list : []\n  } catch { return [] }\n}\n\n/** Effective per-profile snapshot retention cap. */\nexport function resolveKeepSnapshots() {\n  return readGuardConfig().keepSnapshots\n}\n\n/** Effective web port used for health checks (config override, default 3080). */\nexport function resolveGuardPort() {\n  return readGuardConfig().port\n}\n\nfunction writeGuardConfig(cfg) {\n  try {\n    mkdirSync(dirname(guardConfigPath()), { recursive: true })\n  } catch { /* ignore */ }\n  writeFileSync(guardConfigPath(), `${JSON.stringify(cfg, null, 2)}\\n`, 'utf8')\n}\n\n/** Persist the retention cap (clamped to [MIN, MAX]). Returns the stored value. */\nexport function setKeepSnapshots(n) {\n  const num = Math.max(\n    MIN_KEEP_SNAPSHOTS,\n    Math.min(MAX_KEEP_SNAPSHOTS, Math.floor(Number(n) || DEFAULT_KEEP_SNAPSHOTS)),\n  )\n  writeGuardConfig({ ...readGuardConfig(), keepSnapshots: num })\n  return num\n}\n\nexport function listProfiles() {\n  const dir = profilesDir()\n  if (!existsSync(dir)) return []\n  return readdirSync(dir, { withFileTypes: true })\n    .filter((e) => e.isDirectory() && e.name !== 'node_modules' && !e.name.startsWith('_'))\n    .map((e) => e.name)\n    .sort()\n}\n\nfunction stamp() {\n  const d = new Date()\n  const p = (n, w = 2) => String(n).padStart(w, '0')\n  return `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}-${p(d.getMilliseconds(), 3)}`\n}\n\nfunction sha256File(path) {\n  return createHash('sha256').update(readFileSync(path)).digest('hex')\n}\n\nfunction isWin() {\n  return process.platform === 'win32'\n}\n\n/** Resolve a usable pnpm launcher. Explicit env override wins; PATH is tried\n * next; finally the harness-local .bin. Returns null when nothing exists. */\nexport function resolvePnpmCommand() {\n  const candidates = [\n    process.env.DSH_GUARD_PNPM ?? '',\n    'pnpm',\n    join(dirname(dshHome()), 'node_modules', '.bin', isWin() ? 'pnpm.cmd' : 'pnpm'),\n    join(dshHome(), 'node_modules', '.bin', isWin() ? 'pnpm.cmd' : 'pnpm'),\n  ]\n  for (const candidate of candidates) {\n    if (!candidate) continue\n    if (candidate === 'pnpm') {\n      // PATH probe; on Windows go through cmd.exe to run pnpm.cmd without a shell.\n      const probe = isWin()\n        ? spawnSync('cmd.exe', ['/d', '/s', '/c', 'pnpm --version'], { encoding: 'utf8' })\n        : spawnSync('pnpm', ['--version'], { encoding: 'utf8' })\n      if (probe.status === 0) return candidate\n      continue\n    }\n    if (existsSync(candidate)) return candidate\n  }\n  return null\n}\n\n/** Windows cmd token: quote only when it contains whitespace/quotes. A bare\n * token stays unquoted so cmd still resolves it via PATH (a quoted bare name\n * like \"pnpm\" makes cmd skip the PATH lookup). */\nfunction cmdToken(s) {\n  return /[\\s\"]/.test(s) ? `\"${String(s).replace(/\"/g, '\"\"')}\"` : String(s)\n}\n\n/** Run pnpm. On Windows the launcher is a .cmd, so it is invoked through\n * cmd.exe explicitly (no `shell: true`, no unescaped-argument warning).\n * Tokens are quoted only when they contain whitespace/quotes: quoting a bare\n * command name breaks cmd's PATH lookup, and Node's spawnSync command-line\n * escaping additionally mangles per-arg quotes passed to cmd /c. The probe in\n * resolvePnpmCommand already uses this unquoted shape and works. */\nex